40	  it("quotes 7 runes at 175 G base premium (no block -- 7 is not exactly 3) -- 197.5 G, rounded up to 198 G", () => {
41	    const sevenRunes = Array.from({ length: 7 }, () => ({ type: "rune" }));
42	    expect(quote({ yearsWithMHPCO: 0 }, sevenRunes)).toBe(198);
43	  });
44	
45	  // --- "Alike" means exactly the same type, not the same family ---
46	  it("quotes 2 runes + 1 moonstone at 75 G base premium (no block: different types) -- 87.5 G, rounded up to 88 G", () => {
47	    const items = [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }];
48	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(88);
49	  });
50	  it("quotes 3 runes + 3 moonstones at 120 G base premium (two separate blocks of the same type) -- 137 G total", () => {
51	    const runes = Array.from({ length: 3 }, () => ({ type: "rune" }));
52	    const moonstones = Array.from({ length: 3 }, () => ({ type: "moonstone" }));
53	    expect(quote({ yearsWithMHPCO: 0 }, [...runes, ...moonstones])).toBe(137);
54	  });
55	
56	  // --- Item-specific modifiers ---
57	  it("adds a 50 % curse surcharge to a cursed sword's base premium -- 100 G + 50 G curse + 10 G first insurance + 5 G fee = 165 G", () => {
58	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", cursed: true }])).toBe(165);
59	  });
60	  it("adds a 30 % high-enchantment surcharge to a sword with enchantment 5 (threshold met) -- 145 G", () => {
61	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", enchantment: 5 }])).toBe(145);
62	  });
63	  it("adds no high-enchantment surcharge to a sword with enchantment 4 (below threshold) -- 115 G", () => {
64	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", enchantment: 4 }])).toBe(115);
65	  });
66	  it("adds both curse and high-enchantment surcharges to a cursed sword with enchantment 5 -- 195 G", () => {
67	    const sword = { type: "sword", cursed: true, enchantment: 5 };
68	    expect(quote({ yearsWithMHPCO: 0 }, [sword])).toBe(195);
69	  });
70	  it("applies item-specific surcharges only to the affected item: cursed sword + plain amulet -> 210 G before policy modifiers and fee, 231 G in total", () => {
71	    const items = [{ type: "sword", cursed: true }, { type: "amulet" }];
72	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(231);
73	  });
74	
75	  // --- Policy-wide modifiers ---
76	  it("applies the 20 % loyalty discount to the policy base premium for a customer with exactly 2 years with MHPCO -- 95 G", () => {
77	    expect(quote({ yearsWithMHPCO: 2 }, [{ type: "sword" }])).toBe(95);
78	  });
79	  it("applies no loyalty discount for a customer with 1 year with MHPCO -- 115 G", () => {
80	    expect(quote({ yearsWithMHPCO: 1 }, [{ type: "sword" }])).toBe(115);
81	  });
82	  it("applies the 10 % first-insurance surcharge on the policy base premium -- plain sword 115 G", () => {
83	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }])).toBe(115);
